/**
 * The hash printed on a legal page, and stamped into every acceptance row, is a claim that the text
 * a customer read is the text they agreed to. Nothing else in the system checks that claim — the
 * hash is generated by a script someone has to remember to run, and a document edited without
 * re-running it would publish a stale hash while looking completely correct.
 *
 * These tests recompute the hashes FROM THE MARKDOWN, on purpose, rather than importing anything
 * from scripts/hash-legal.mjs. A test that verifies a generator by calling the generator only
 * proves the generator is deterministic. The five lines of normalise-and-hash below are duplicated
 * deliberately, and that duplication is the test.
 */

const fs = require('fs')
const path = require('path')
const crypto = require('crypto')

const { LEGAL_META, LEGAL_PRIOR_META } = require('./generated/legalMeta')
const { LEGAL_TEXT, LEGAL_PRIOR_TEXT } = require('./generated/legalText')
const {
  DOC_TYPES, legalDoc, priorLegalDoc, PRIOR_VERSIONS, isDraft, missingLegalValues, acceptancePayload,
  loadLegalText,
} = require('./index')

const PRIOR_KEYS = Object.keys(PRIOR_VERSIONS)
const versionInName = (filename) => (/-v(\d+\.\d+)\.md$/.exec(filename) || [])[1]

function readCanonical(filename) {
  const raw = fs.readFileSync(path.join(__dirname, filename), 'utf8')
  return raw.replace(/^﻿/, '').replace(/\r\n/g, '\n')
}

function sha256(text) {
  return crypto.createHash('sha256').update(text, 'utf8').digest('hex')
}

describe('legal document hashes', () => {
  it.each(DOC_TYPES)('%s: committed hash matches the markdown on disk', (docType) => {
    const meta = LEGAL_META[docType]
    expect(meta).toBeDefined()
    const canonical = readCanonical(meta.filename)
    expect(sha256(canonical)).toBe(meta.sha256)
  })

  it.each(DOC_TYPES)('%s: bundled text is byte-identical to the markdown', (docType) => {
    const canonical = readCanonical(LEGAL_META[docType].filename)
    expect(LEGAL_TEXT[docType]).toBe(canonical)
  })

  it.each(DOC_TYPES)('%s: byte count is recorded correctly', (docType) => {
    const canonical = readCanonical(LEGAL_META[docType].filename)
    expect(Buffer.byteLength(canonical, 'utf8')).toBe(LEGAL_META[docType].bytes)
  })

  // The hash is only verifiable by a third party if it is over LF bytes. A file that had picked up
  // CRLF would still hash consistently here (the normaliser runs on both sides) but would no longer
  // match what a customer gets from `sha256sum` on the file they downloaded from git.
  it.each(DOC_TYPES)('%s: markdown on disk contains no CRLF', (docType) => {
    const raw = fs.readFileSync(path.join(__dirname, LEGAL_META[docType].filename), 'utf8')
    expect(raw).not.toMatch(/\r\n/)
  })
})

// A superseded version is served at /legal/<doc>/<version> with its own text and hash, because every
// acceptance row links to the version it recorded. Its file must therefore never change after it
// is published, and these hold it to the bytes on disk exactly as the current version is held.
describe('prior version hashes', () => {
  it('there is at least one prior version (Privacy 1.0), so these tests are not vacuous', () => {
    expect(PRIOR_KEYS).toContain('privacy-1.0')
  })

  it.each(PRIOR_KEYS)('%s: committed hash, bytes and bundled text match the markdown on disk', (key) => {
    const meta = LEGAL_PRIOR_META[key]
    expect(meta).toBeDefined()
    const canonical = readCanonical(meta.filename)
    expect(sha256(canonical)).toBe(meta.sha256)
    expect(Buffer.byteLength(canonical, 'utf8')).toBe(meta.bytes)
    expect(LEGAL_PRIOR_TEXT[key]).toBe(canonical)
    expect(fs.readFileSync(path.join(__dirname, meta.filename), 'utf8')).not.toMatch(/\r\n/)
  })

  it.each(PRIOR_KEYS)('%s: priorLegalDoc() carries its own version, dates and hash', (key) => {
    const p = PRIOR_VERSIONS[key]
    const doc = priorLegalDoc(p.docType, p.version)
    expect(doc.sha256).toBe(LEGAL_PRIOR_META[key].sha256)
    expect(doc.sha256).not.toBe(legalDoc(p.docType).sha256)
    expect(versionInName(doc.filename)).toBe(p.version)
    expect(doc.effectiveAd).toMatch(/^\d{4}-\d{2}-\d{2}$/)
  })
})

describe('loadLegalText', () => {
  it('serves the current version with or without a version in the address', async () => {
    const privacy = legalDoc('privacy')
    const canonical = readCanonical(privacy.filename)
    expect(await loadLegalText('privacy')).toBe(canonical)
    expect(await loadLegalText('privacy', privacy.version)).toBe(canonical)
  })

  it('serves a superseded version its OWN text, never the current wording', async () => {
    const text = await loadLegalText('privacy', '1.0')
    expect(text).toBe(readCanonical('privacy-v1.0.md'))
    expect(text).not.toBe(LEGAL_TEXT.privacy)
    expect(text).toContain('**Version 1.0 ')
  })

  it('returns null for a version this bundle does not hold, and for an unknown document', async () => {
    expect(await loadLegalText('privacy', '0.9')).toBeNull()
    expect(await loadLegalText('terms', '1.1')).toBeNull()
    expect(await loadLegalText('cookies')).toBeNull()
  })
})

describe('registry and generated metadata agree', () => {
  it('every registered document has generated metadata, and vice versa', () => {
    expect(Object.keys(LEGAL_META).sort()).toEqual([...DOC_TYPES].sort())
    expect(Object.keys(LEGAL_TEXT).sort()).toEqual([...DOC_TYPES].sort())
    expect(Object.keys(LEGAL_PRIOR_META).sort()).toEqual([...PRIOR_KEYS].sort())
    expect(Object.keys(LEGAL_PRIOR_TEXT).sort()).toEqual([...PRIOR_KEYS].sort())
  })

  // The filename is where a version is written next to its text. A registry that says 1.1 over a
  // file named -v1.0 would stamp every acceptance with a version its hash does not belong to.
  it.each(DOC_TYPES)('%s: the registry version is the version in the current file name', (docType) => {
    expect(versionInName(LEGAL_META[docType].filename)).toBe(legalDoc(docType).version)
  })

  it.each(DOC_TYPES)('%s: legalDoc() exposes a non-empty hash and version', (docType) => {
    const doc = legalDoc(docType)
    expect(doc.sha256).toMatch(/^[0-9a-f]{64}$/)
    expect(doc.version).toMatch(/^\d+\.\d+$/)
    expect(doc.effectiveAd).toMatch(/^\d{4}-\d{2}-\d{2}$/)
    expect(doc.effectiveBs).toMatch(/^\d{4}-\d{2}-\d{2}$/)
  })
})

describe('draft detection', () => {
  // Not an assertion that the documents ARE complete — they are not yet, and this test must not
  // start failing merely because someone filled the company registration number in. It asserts the
  // detector works, which is what stops a page with a raw placeholder being presented as in force.
  it('reports a document with an unfilled placeholder as a draft', () => {
    const drafts = DOC_TYPES.filter(isDraft)
    const withMarkers = DOC_TYPES.filter(
      (t) => (LEGAL_META[t].missing || []).length > 0
    )
    expect(drafts.sort()).toEqual(withMarkers.sort())
  })

  it('missingLegalValues() is the union across documents, deduplicated and sorted', () => {
    const expected = [
      ...new Set(DOC_TYPES.flatMap((t) => LEGAL_META[t].missing || [])),
    ].sort()
    expect(missingLegalValues()).toEqual(expected)
  })

  it('no document still contains a placeholder marker the detector did not report', () => {
    for (const docType of DOC_TYPES) {
      const found = [
        ...new Set(
          [...LEGAL_TEXT[docType].matchAll(/\[\[NEEDS VALUE: ([A-Z0-9_]+)\]\]/g)].map((m) => m[1])
        ),
      ].sort()
      expect(found).toEqual([...(LEGAL_META[docType].missing || [])].sort())
    }
  })
})

describe('acceptancePayload', () => {
  it('carries a version and hash for every document and nothing else', () => {
    const payload = acceptancePayload()
    expect(Object.keys(payload).sort()).toEqual([...DOC_TYPES].sort())
    for (const docType of DOC_TYPES) {
      expect(Object.keys(payload[docType]).sort()).toEqual(['sha256', 'version'])
      expect(payload[docType].sha256).toBe(LEGAL_META[docType].sha256)
    }
  })

  // The server reads identity and address off the request. A payload that offered them would be
  // inviting the browser to attribute its own acceptance, which is the defect this whole design
  // exists to avoid — so assert they are absent rather than trusting the shape stays as written.
  it('never carries identity or address fields', () => {
    const serialised = JSON.stringify(acceptancePayload())
    for (const forbidden of ['ip', 'user_id', 'userId', 'client_id', 'clientId', 'user_agent']) {
      expect(serialised).not.toContain(forbidden)
    }
  })
})
